#include "core.h"
#include <set>

namespace clockapp {
int SelfTest() {
    int passed=0;std::string report;
    auto assertTrue=[](bool condition){if(!condition)throw std::runtime_error("Native self-test assertion failed.");};
    auto test=[&](const char* name,const std::function<void()>& run){run();report+="PASS "+std::string(name)+"\n";++passed;};
    test("camera precedence",[&]{assertTrue((Capture{true,true}).mode()==Mode::Camera);assertTrue((Capture{false,true}).mode()==Mode::Microphone);assertTrue((Capture{}).mode()==Mode::Idle);});
    test("release delay and immediate activation",[&]{Latch latch{800,{}};assertTrue(!latch.Update(false,0));assertTrue(latch.Update(true,100));assertTrue(latch.Update(false,899));assertTrue(!latch.Update(false,900));});
    test("idle never dismisses unrelated notifications",[&]{int calls=0;Alerts alerts(2000,[&](Mode){++calls;},[&]{++calls;});alerts.Tick(Mode::Idle,0);alerts.Tick(Mode::Idle,10000);alerts.Clear();assertTrue(calls==0);});
    test("held alerts send once and update color on state changes",[&]{std::vector<Mode> calls;Alerts alerts(2000,[&](Mode m){calls.push_back(m);},[]{});alerts.Tick(Mode::Camera,0);alerts.Tick(Mode::Camera,2000);alerts.Tick(Mode::Camera,900000);assertTrue(calls.size()==1);alerts.Tick(Mode::Microphone,900001);assertTrue(calls==std::vector<Mode>({Mode::Camera,Mode::Microphone}));});
    test("capture stop clears once",[&]{int clear=0;Alerts alerts(2000,[](Mode){},[&]{++clear;});alerts.Tick(Mode::Camera,0);alerts.Tick(Mode::Idle,1);alerts.Tick(Mode::Idle,9999);assertTrue(clear==1);});
    test("failed push remains eligible for cleanup",[&]{int push=0,clear=0;Alerts alerts(2000,[&](Mode){++push;throw std::runtime_error("offline");},[&]{++clear;});try{alerts.Tick(Mode::Camera,0);}catch(const std::runtime_error&){}alerts.Tick(Mode::Camera,500);alerts.Tick(Mode::Idle,501);assertTrue(push==1&&clear==1);});
    test("failed dismiss retries after recovery",[&]{int clears=0;Alerts alerts(2000,[](Mode){},[&]{if(++clears==1)throw std::runtime_error("offline");});alerts.Tick(Mode::Microphone,0);try{alerts.Tick(Mode::Idle,1);}catch(const std::runtime_error&){}alerts.Tick(Mode::Idle,1000);assertTrue(clears==1);alerts.Tick(Mode::Idle,2001);assertTrue(clears==2);});
    test("failed push recovers without state change then stops retrying",[&]{int pushes=0;Alerts alerts(2000,[&](Mode){if(++pushes==1)throw std::runtime_error("offline");},[]{});try{alerts.Tick(Mode::Camera,0);}catch(const std::runtime_error&){}alerts.Tick(Mode::Camera,2000);alerts.Tick(Mode::Camera,999999);assertTrue(pushes==2);});
    test("manual dismissal stays dismissed while capture state is unchanged",[&]{int pushes=0;bool displayed=false;Alerts alerts(2000,[&](Mode){++pushes;displayed=true;},[&]{displayed=false;});alerts.Tick(Mode::Microphone,0);displayed=false;alerts.Tick(Mode::Microphone,999999);assertTrue(!displayed&&pushes==1);alerts.Tick(Mode::Idle,1000000);alerts.Tick(Mode::Microphone,1000001);assertTrue(displayed&&pushes==2);});
    test("explicit clear resets state for a subsequent test or session",[&]{int pushes=0,clears=0;Alerts alerts(2000,[&](Mode){++pushes;},[&]{++clears;});alerts.Tick(Mode::Camera,0);alerts.Clear();alerts.Tick(Mode::Camera,1);assertTrue(pushes==2&&clears==1);});
    test("pixel height margins and four-column word gap",[&]{auto p=SignPixels();std::set<int> x,y;for(auto v:p){x.insert(v.first);y.insert(v.second);}assertTrue(*x.begin()==3&&*x.rbegin()==28);assertTrue(y==std::set<int>({1,2,3,4,5,6}));for(int c=12;c<=15;++c)assertTrue(!x.count(c));assertTrue(p.size()==66);});
    test("payload uses held named ownership without an expiry timer",[&]{auto json=Payload(Settings{},Mode::Camera);assertTrue(json.find("durationMs")==std::string::npos);assertTrue(json.find("\"hold\":true")!=std::string::npos);assertTrue(json.find("\"stack\":false")!=std::string::npos);assertTrue(json.find("\"backgroundColor\":\"#FF0000\"")!=std::string::npos);assertTrue(Payload(Settings{},Mode::Microphone).find("#B86000")!=std::string::npos);});
    test("settings JSON round trip with Unicode and escapes",[&]{Settings settings;settings.username=L"test \\";settings.username+=L"\u540d";auto restored=Settings::Parse(settings.Json());assertTrue(restored.username==settings.username);auto unicode=Settings::Parse("{\"Username\":\"\\u540d\\u0022\"}");assertTrue(unicode.username==L"\u540d\"");});
    test("invalid URL and timing rejected",[&]{int rejected=0;for(const auto& json:{"{\"ClockUrl\":\"ftp://clock\"}","{\"ClockUrl\":\"http://user:password@clock\"}","{\"ClockUrl\":\"http://clock/path\"}","{\"TestMs\":0}","{\"CameraColor\":\"red\"}"})try{Settings::Parse(json);}catch(const std::exception&){++rejected;}assertTrue(rejected==5);});
    test("Windows encrypted credential round trip",[&]{wchar_t temp[32768];GetTempPathW(32768,temp);Store store{fs::path(temp)/(L"OnAirClock-test-"+std::to_wstring(GetCurrentProcessId()))};fs::create_directories(store.directory);try{store.Save(Settings{},"native-test-secret");assertTrue(store.Password()=="native-test-secret");assertTrue(store.Load().url==L"http://awtrix.local");}catch(...){fs::remove(store.directory/L"settings.json");fs::remove(store.directory/L"password.dpapi");fs::remove(store.directory);throw;}fs::remove(store.directory/L"settings.json");fs::remove(store.directory/L"password.dpapi");fs::remove(store.directory);});
    report+=std::to_string(passed)+" native tests passed.\n";DWORD n=0;WriteFile(GetStdHandle(STD_OUTPUT_HANDLE),report.data(),static_cast<DWORD>(report.size()),&n,nullptr);return 0;
}
}
